def comps(g,val=None):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] and (r,c) not in seen and (val is None or g[r][c]==val):
                st=[(r,c)]; cells=set(); col=g[r][c]
                while st:
                    y,x=st.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); cells.add((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and (ny,nx) not in seen: st.append((ny,nx))
                out.append((col,cells))
    return out

def norm(cells):
    ys=[y for y,x in cells]; xs=[x for y,x in cells]
    r0,c0=min(ys),min(xs)
    return tuple(sorted((y-r0,x-c0) for y,x in cells))

